using System;using System.Data;using System.Text;public partial class SearchGames:System.Web.UI.Page{public string resultsHtml="";protected void Page_Load(object sender,EventArgs e){if(Page.IsPostBack){string q=MyAdoHelper.FixText(Request.Form["searchText"]);string sql="SELECT Games.GameDate,Games.League,A.ClubName AS ClubA,B.ClubName AS ClubB,Games.GameResult FROM Games INNER JOIN Clubs A ON Games.ClubAId=A.ClubId INNER JOIN Clubs B ON Games.ClubBId=B.ClubId WHERE A.ClubName LIKE N'%"+q+"%' OR B.ClubName LIKE N'%"+q+"%'";DataTable dt=MyAdoHelper.ExecuteDataTable(sql);StringBuilder s=new StringBuilder("<table class='dataTable'><tr><th>משחק</th><th>ליגה</th><th>תאריך</th><th>תוצאה</th></tr>");for(int i=0;i<dt.Rows.Count;i++)s.Append("<tr><td>"+dt.Rows[i]["ClubA"]+" נגד "+dt.Rows[i]["ClubB"]+"</td><td>"+dt.Rows[i]["League"]+"</td><td>"+Convert.ToDateTime(dt.Rows[i]["GameDate"]).ToString("dd/MM/yyyy HH:mm")+"</td><td>"+dt.Rows[i]["GameResult"]+"</td></tr>");s.Append("</table>");resultsHtml=s.ToString();}}}